import numpy as np

class SecureAggregator:
    def __init__(self, num_clients, model_shape):
        self.num_clients = num_clients
        self.model_shape = model_shape
    def generate_pairwise_masks(self, seed):
        masks = {}
        for i in range(self.num_clients):
            for j in range(i + 1, self.num_clients):
                np.random.seed(seed + i * 1000 + j)
                mask = np.random.randn(*self.model_shape)
                masks[(i, j)] = mask
                masks[(j, i)] = -mask
        return masks
    def mask_update(self, client_update, client_id, pairwise_masks):
        masked = client_update.copy()
        for j in range(self.num_clients):
            if j != client_id:
                masked += pairwise_masks[(client_id, j)]
        return masked
    def aggregate_masked(self, masked_updates):
        return sum(masked_updates)
    def secure_aggregate(self, client_updates, seed):
        pairwise_masks = self.generate_pairwise_masks(seed)
        masked_updates = [self.mask_update(u, i, pairwise_masks) for i, u in enumerate(client_updates)]
        return self.aggregate_masked(masked_updates)
